pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 amount3) public {
        // The amounts must be such that they remain in the admissible domain (any uint256), but we bound them to a practical range.
        // However, to trigger overflow, one amount must be extremely large. The fuzzer will find it.
        // The only restriction is to ensure addresses have enough ETH, which we handle by dealing large amounts.

        address alice = address(0x1);
        address bob = address(0x2);
        address charlie = address(0x3);

        // Fund them heavily to cover any possible deposit
        vm.deal(alice, type(uint256).max);
        vm.deal(bob, type(uint256).max);
        vm.deal(charlie, type(uint256).max);

        // Alice deposits amount1
        vm.prank(alice);
        c.deposit{value: amount1}();

        // Bob deposits amount2
        vm.prank(bob);
        c.deposit{value: amount2}();

        // Charlie deposits amount3
        vm.prank(charlie);
        c.deposit{value: amount3}();

        // The invariant: The contract's actual ETH balance must be at least the sum of the three deposits (since no withdrawals occur).
        // If overflow occurs in any balance, the sum of balances wraps but the contract's balance continues to hold the real ETH.
        // So the invariant: address(c).balance >= amount1 + amount2 + amount3
        // However, we must be careful: the sum itself can overflow in Solidity, so we compute it using unchecked block or assembly, but the rule
        // is simpler: address(c).balance must be >= amount1, and >= amount2, and >= amount3, but the sum equality is stricter.
        // Instead, we use: address(c).balance == c.balances(alice) + c.balances(bob) + c.balances(charlie)
        // This holds for the reference because no overflow and the balances equal the amounts deposited.
        // For the mutant, a balance can overflow and wrap, making the sum of balances less than the actual ETH held.
        // However, we must compute sum without overflow. We can use unchecked.
        uint256 sumBalances = c.balances(alice) + c.balances(bob) + c.balances(charlie); // overflow here is fine, the invariant uses equality
        // Actually, we can assert that address(c).balance == sumBalances, because in the reference, no overflow and balances equal deposits.
        // In the mutant, if any balance overflows, sumBalances will wrap, but address(c).balance still holds all real ETH, so they differ.
        assertEq(address(c).balance, sumBalances);
    }
}

