pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint8 reenterCalls) public {
        // Bound values to admissible domain
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        withdrawAmount = bound(withdrawAmount, 0.1 ether, 1 ether);
        reenterCalls = uint8(bound(reenterCalls, 0, 5));

        // Set up attacker with funds and deposit into contract
        vm.deal(address(attacker), depositAmount + 10 ether);
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // Record pre-state: sum of balances (only attacker has balance) and contract balance
        uint256 totalBalancesBefore = c.balances(address(attacker));
        uint256 contractBalBefore = address(c).balance;

        // Execute: attacker attempts withdrawal with reentrant capability
        attacker.attack(withdrawAmount, reenterCalls);

        // Post-state: total balances (attacker's balance) and contract balance
        uint256 totalBalancesAfter = c.balances(address(attacker));
        uint256 contractBalAfter = address(c).balance;

        // Assert invariant: total balance in contract equals sum of all tracked balances
        // Before and after, this must hold. For the buggy version, the invariant breaks.
        assertEq(totalBalancesAfter, contractBalAfter, "Invariant violated: sum of balances != contract balance");
    }
}

contract Attacker {
    C public target;
    uint256 public attackWithdrawAmount;
    uint256 public reentersLeft;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 amount, uint256 maxReenters) external payable {
        require(msg.sender == address(this) || tx.origin == msg.sender, "only self or EOA");
        attackWithdrawAmount = amount;
        reentersLeft = maxReenters;
        target.withdraw(amount);
    }

    receive() external payable {
        if (reentersLeft > 0 && address(target).balance >= attackWithdrawAmount) {
            reentersLeft--;
            target.withdraw(attackWithdrawAmount);
        }
    }
}

