pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount0, uint256 amount1) public {
        amount0 = bound(amount0, 1, 100 ether);
        amount1 = bound(amount1, 1, 100 ether);
        uint256 total = amount0 + amount1;
        vm.assume(total >= amount0 && total >= amount1);

        address caller = address(new ReenteringWithdrawer(c));
        vm.deal(caller, total);
        vm.prank(caller);
        c.deposit{value: total}();

        uint256 balanceBefore = c.balances(caller);
        vm.prank(caller);
        ReenteringWithdrawer(caller).start(amount0, amount1);
        uint256 balanceAfter = c.balances(caller);

